["GenericTelegraph"] = function()
local Action = getfenv().Action
local players = game:GetService("Players")
return function(self, timing)
local selfCharacter = players.LocalPlayer.Character;
if self.owner ~= selfCharacter then
return
end
local effectData = self.data;
local telegraphType = effectData.telegraph;
local part = effectData.part;
if part and part:IsDescendantOf(selfCharacter) and part.Name == "HumanoidRootPart" then                 local dur = effectData.dur;                 if dur ~= 1 then
return;
end
if not table.find({
"dodge_only",
"block_only",
"parry_only"
}, telegraphType) then return; end
self:hook("target", function(_)
return true
end)
local action = Action.new()
action._when = 950         	    action._type = telegraphType == "dodge_only" and "Dodge" or "Parry"
action.ihbc = true
action.name = "Dynamic Weapon Manual Timing"
return self:action(timing, action)
end
return;
end
end,
