["OwlDisperse"] = function()
local Logger = getfenv().Logger
local RepeatInfo = getfenv().RepeatInfo
local Latency = getfenv().Latency
return function(self, timing)
local owner = self.owner
if not owner then
return
end
local duration = self.data.Duration
if not duration then
return
end
self:hook("rc", function(_, info)
if os.clock() - info.start >= (duration + 0.4) then
return Logger.warn("(%.2f) Stopping RPUE '%s' because we've went past the duration.", duration, timing.name)
end
return true
end)
timing.fhb = false
timing.ndfb = true
timing.rpue = true
timing._rsd = (duration / 2.5) * 1000
timing._rpd = 250
timing.imxd = 120
timing.imdd = 0
local info = RepeatInfo.new(timing, Latency.rdelay(), self:uid(10))
self:srpue(owner, timing, info)
end
end,
["ParasolTendrils"] = function()
local PartTiming = getfenv().PartTiming
local Defense = getfenv().Defense
local Action = getfenv().Action
local TaskSpawner = getfenv().TaskSpawner
local Latency = getfenv().Latency
local players = game:GetService("Players")
local function isAimingAtPlayer(hook)
local character = players.LocalPlayer and players.LocalPlayer.Character
if not character then return false end
local rootPart = character:FindFirstChild("HumanoidRootPart")
if not rootPart then return false end
local toPlayer = (rootPart.Position - hook.Position).Unit
return hook.CFrame.UpVector:Dot(toPlayer) < -0.75
end
return function(self, timing)
local part = self.part
if not part then return end
if not part.Name:match("ParaHook") then return end
local isAiming = false
local startTime = os.clock()
while (os.clock() - startTime) < 1 do
if not part.Parent then return end
if isAimingAtPlayer(part) then
isAiming = true
break
end
task.wait()
end
if not isAiming then return end
local elapsed = os.clock() - startTime
if self:distance(part) <= 100 then
TaskSpawner.spawn("ParasolTendrilClose", function()
task.wait(math.max(0, 1.35 - Latency.rtt() - elapsed))
local action = Action.new()
action._when = 0
action._type = "Parry"
action.ihbc = true
action.name = "Parasol Tendril Close Parry"
self:action(timing, action)
end)
return
end
local action = Action.new()
action._when = 0
action._type = "Parry"
action.ihbc = true
action.name = "Parasol Tendril Parry"
local pt = PartTiming.new()
pt.uhc = true
pt.duih = true
pt.fhb = false
pt.name = "Parasol Tendril"
pt.hitbox = Vector3.new(25, 200, 25)
pt.actions:push(action)
pt.cbm = true
Defense.cdpo(part, pt)
end
end,
