return
end
for _, instance in next, gestureScroll:GetDescendants() do
if not instance:IsA("UIListLayout") and not instance:IsA("UIPadding") then
instance:Destroy()
end
end
for _, instance in next, commScroll:GetDescendants() do
if not instance:IsA("UIListLayout") and not instance:IsA("UIPadding") then
instance:Destroy()
end
end
