local function initNearbyEventLogger(groupbox)
local Players = game:GetService("Players")
local Workspace = game:GetService("Workspace")
local loggerEnabled = false
local detectionRange = 100
local connections = {}
local hookedAnimators = {}
local lastLogged = setmetatable({}, { __mode = "k" })
local function disconnectAll()
for _, connection in ipairs(connections) do
pcall(function() connection:Disconnect() end)
end
 table.clear(connections)
 table.clear(hookedAnimators)
end
local function getPosition(instance)
local node = instance
while node and node ~= Workspace do
if node:IsA("BasePart") then return node.Position end
if node:IsA("Attachment") then return node.WorldPosition end
if node:IsA("Model") then
local root = node:FindFirstChild("HumanoidRootPart") or node.PrimaryPart
if root and root:IsA("BasePart") then return root.Position end
end
node = node.Parent
end
return nil
end
local function nearbyDistance(instance)
local position = getPosition(instance)
local character = Players.LocalPlayer and Players.LocalPlayer.Character
local root = character and character:FindFirstChild("HumanoidRootPart")
if not position or not root then return nil end
local distance = (position - root.Position).Magnitude
if distance <= detectionRange then return math.floor(distance + 0.5) end
return nil
end
local function logEvent(kind, instance, detail)
if not loggerEnabled then return end
local distance = nearbyDistance(instance)
if not distance then return end
local now = os.clock()
if lastLogged[instance] and now - lastLogged[instance] < 1.5 then return end
lastLogged[instance] = now
print(string.format("[Nearby Event Logger] %s | %s | %d studs", kind, detail, distance))
end
local function hookAnimator(animator)
if hookedAnimators[animator] then return end
hookedAnimators[animator] = true
local connection = animator.AnimationPlayed:Connect(function(track)
if not loggerEnabled then return end
local animation = track and track.Animation
local id = animation and animation.AnimationId or "unknown animation"
logEvent("Animation", animator, tostring(id))
end)
table.insert(connections, connection)
end
local function inspect(instance)
if instance:IsA("Animator") then hookAnimator(instance) end
if instance:IsA("Sound") then
local connection = instance.Played:Connect(function()
logEvent("Sound", instance, instance.SoundId ~= "" and instance.SoundId or instance.Name)
end)
table.insert(connections, connection)
elseif instance:IsA("ParticleEmitter") or instance:IsA("Trail") or instance:IsA("Beam") or instance:IsA("Highlight") then
logEvent("Effect", instance, instance.ClassName .. " (" .. instance.Name .. ")")
end
end
local function startLogger()
if loggerEnabled then return end
loggerEnabled = true
for _, instance in ipairs(Workspace:GetDescendants()) do inspect(instance) end
table.insert(connections, Workspace.DescendantAdded:Connect(function(instance)
if loggerEnabled then inspect(instance) end
end))
print("[Nearby Event Logger] Enabled. Events will appear in the console.")
end
local function stopLogger()
loggerEnabled = false
disconnectAll()
print("[Nearby Event Logger] Disabled.")
end
