__bundle_register("Menu/VisualsTab", function(require, _LOADED, __bundle_register, __bundle_modules)
local Icons = require("GUI/Icons")
local Logger = require("Utility/Logger")
local Configuration = require("Utility/Configuration")
local Visuals = require("Features/Visuals/Visuals")
local JSON = require("Utility/JSON")
local BuilderData = require("Features/Visuals/Objects/BuilderData")
local Players = game:GetService("Players")
local VisualsTab = {}

-- Nearby event logger. This is passive: it only observes client-visible events and prints them.
local EventLogger = {
Enabled = false,
Range = 100,
Connections = {},
AnimatorConnections = {},
SoundConnections = {},
Last = {},
Cooldown = 0.15,
}

local function eventLoggerDisconnect(list)
for _, connection in next, list do
pcall(function() connection:Disconnect() end)
end
table.clear(list)
end

local function eventLoggerRoot(instance)
local current = instance
for _ = 1, 8 do
if not current then break end
if current:IsA("BasePart") then return current end
if current:IsA("Model") then
local root = current:FindFirstChild("HumanoidRootPart") or current.PrimaryPart
if root and root:IsA("BasePart") then return root end
end
current = current.Parent
end
return nil
end

local function eventLoggerDistance(instance)
local root = eventLoggerRoot(instance)
local character = Players.LocalPlayer and Players.LocalPlayer.Character
local myRoot = character and character:FindFirstChild("HumanoidRootPart")
if not root or not myRoot then return nil end
local distance = (root.Position - myRoot.Position).Magnitude
if distance > EventLogger.Range then return nil end
return distance
end

local function eventLoggerName(instance)
if not instance then return "?" end
return instance:GetFullName()
end

local function eventLoggerPrint(kind, instance, extra)
if not EventLogger.Enabled then return end
local distance = eventLoggerDistance(instance)
if not distance then return end
local key = kind .. "|" .. eventLoggerName(instance) .. "|" .. tostring(extra or "")
local now = os.clock()
local last = EventLogger.Last[key]
if last and now - last < EventLogger.Cooldown then return end
EventLogger.Last[key] = now
print(string.format("[Nearby %s] %.1f studs | %s%s", kind, distance, eventLoggerName(instance), extra and (" | " .. tostring(extra)) or ""))
end

local function eventLoggerWatchAnimator(animator)
if EventLogger.AnimatorConnections[animator] then return end
EventLogger.AnimatorConnections[animator] = animator.AnimationPlayed:Connect(function(track)
if not EventLogger.Enabled then return end
local animation = track and track.Animation
local id = animation and animation.AnimationId or "unknown"
eventLoggerPrint("Animation", animator, "ID=" .. tostring(id))
end)
end

local function eventLoggerWatchSound(sound)
if EventLogger.SoundConnections[sound] then return end
local connection = sound:GetPropertyChangedSignal("Playing"):Connect(function()
if sound.Playing then
local id = sound.SoundId
 eventLoggerPrint("Sound", sound, "ID=" .. tostring(id))
end
end)
EventLogger.SoundConnections[sound] = connection
if sound.Playing then
local id = sound.SoundId
eventLoggerPrint("Sound", sound, "ID=" .. tostring(id))
end
end

local function eventLoggerWatchDescendant(instance)
if instance:IsA("Animator") then
 eventLoggerWatchAnimator(instance)
elseif instance:IsA("Sound") then
 eventLoggerWatchSound(instance)
elseif instance:IsA("ParticleEmitter") or instance:IsA("Trail") or instance:IsA("Beam") or instance:IsA("Highlight") then
 eventLoggerPrint("Effect", instance, "Class=" .. instance.ClassName)
end
end

function EventLogger.Start()
if EventLogger.Enabled then return end
EventLogger.Enabled = true
EventLogger.Last = {}
for _, descendant in next, workspace:GetDescendants() do
 eventLoggerWatchDescendant(descendant)
end
EventLogger.Connections[#EventLogger.Connections + 1] = workspace.DescendantAdded:Connect(eventLoggerWatchDescendant)
Logger.notify("Nearby event logger enabled.")
end

function EventLogger.Stop()
if not EventLogger.Enabled then return end
EventLogger.Enabled = false
eventLoggerDisconnect(EventLogger.Connections)
for animator, connection in next, EventLogger.AnimatorConnections do
pcall(function() connection:Disconnect() end)
EventLogger.AnimatorConnections[animator] = nil
end
for sound, connection in next, EventLogger.SoundConnections do
pcall(function() connection:Disconnect() end)
EventLogger.SoundConnections[sound] = nil
end
EventLogger.Last = {}
Logger.notify("Nearby event logger disabled.")
end

function VisualsTab.initNearbyEventLogger(groupbox)
local toggle = groupbox:AddToggle("NearbyEventLogger", {
Text = "Nearby Event Logger",
Tooltip = "Logs nearby animations, effects, and sounds to the console.",
