Default = 100,
Rounding = 0,
Suffix = " studs",
})
range:OnChanged(function(value)
EventLogger.Range = value
end)
toggle:OnChanged(function(state)
if state then EventLogger.Start() else EventLogger.Stop() end
end)
end
